const reqs = network.requests().filter(r => r.url.includes('/api/tasks'));
const post = reqs.find(r => r.method === 'POST' && r.url.endsWith('/api/tasks'));
const offer = reqs.find(r => r.method === 'GET' && (r.responseBody || '').includes('"stage":"offers_ready"'));
return JSON.stringify({dispatch_request:{method:post.method,url:post.url,status:post.responseStatus,request_body:post.requestBody,response_body:post.responseBody},offers_response:{method:offer.method,url:offer.url,status:offer.responseStatus,response_body:offer.responseBody}});
